  border-radius: 999px;
  background: var(--cx-surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.22);
  transform: translateX(0);
  transition: transform 160ms ease;
}
.dark .t3e-nc-switch.is-on .t3e-nc-switch-thumb { background: #ffffff; }
.t3e-nc-switch.is-on .t3e-nc-switch-thumb { transform: translateX(14px); }
.t3e-nc-branch-picker { display: flex; min-width: 0; flex: 1 1 auto; align-items: center; justify-content: flex-end; gap: 2px; }
.t3e-nc-branch-picker button { background: transparent !important; border: 0 !important; padding-inline: 4px !important; color: var(--cx-ink-2) !important; font-size: 13px !important; height: 28px !important; }
.t3e-nc-branch-picker svg.lucide { display: none !important; }
.t3e-nc-chevron { pointer-events: none; user-select: none; color: var(--cx-ink-3); font-size: 14px; line-height: 1; margin-left: 2px; }

/* 3.4 inline-file-diff card & clickable file link */
.t3e-fc-row {
  display: flex;
  min-width: 0;
  width: 100%;
  align-items: baseline;
  gap: 6px;
  margin: 0;
  font-size: 14px;
  line-height: 22px;
}
.t3e-fc-verb { flex-shrink: 0; }
.t3e-fc-link {
  display: inline;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 0;
  border-bottom: 1px dotted var(--cx-ink-3);
  border-radius: 0;
  padding: 0 0 1px 0;
  background: transparent;
  color: var(--cx-ink-3);
  font-size: 14px;
  line-height: 22px;
  cursor: pointer;
  transition: color 140ms ease, border-color 140ms ease;
}
.t3e-fc-link:hover { color: var(--cx-ink-1); border-bottom-color: var(--cx-ink-1); border-bottom-style: solid; }
.t3e-fc-stats {
  display: inline-flex;
  flex-shrink: 0;
  align-items: baseline;
  gap: 5px;
  font-family: var(--font-mono);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.t3e-fc-add { color: #16a34a; font-size: 13px; }
.t3e-fc-del { color: #dc2626; font-size: 13px; }
.dark .t3e-fc-add { color: #4ade80; }
.dark .t3e-fc-del { color: #f87171; }
.t3e-diff-card {
  margin: 4px 0 6px;
  border-radius: 10px;
  border: 1px solid var(--cx-line);
  background: var(--cx-surface);
  overflow: hidden;
}
.t3e-diff-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 10px 7px 12px;
  background: var(--cx-card);
  border-bottom: 1px solid var(--cx-line-soft);
}
.t3e-diff-header-left { display: flex; min-width: 0; align-items: baseline; gap: 8px; }
.t3e-diff-title { font-family: var(--font-mono); font-size: 12px; line-height: 18px; color: var(--cx-ink-1); border-bottom-color: transparent; padding: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.t3e-diff-title:hover { color: var(--cx-accent); border-bottom-color: currentColor; border-bottom-style: solid; }
.t3e-diff-header-actions { display: flex; flex-shrink: 0; align-items: center; gap: 4px; }
.t3e-diff-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 6px;
  padding: 0;
  background: transparent;
  color: var(--cx-ink-3);
  font-size: 12px;
  cursor: pointer;
  transition: background-color 120ms ease, color 120ms ease;
}
.t3e-diff-icon-btn:hover { background: var(--cx-hover); color: var(--cx-ink-1); }
.t3e-diff-btn-icon { width: 14px; height: 14px; }
.t3e-diff-body {
  max-height: min(19rem, 40dvh);
  overflow: auto;
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 19px;
}
.t3e-diff-body::-webkit-scrollbar { width: 6px; height: 6px; }
.t3e-diff-line { display: flex; min-width: max-content; width: 100%; border-left: 3px solid transparent; padding: 0 12px 0 0; }
.t3e-diff-line.is-add { background: rgba(34, 197, 94, 0.11); border-left-color: #16a34a; }
.t3e-diff-line.is-del { background: rgba(239, 68, 68, 0.10); border-left-color: #dc2626; }
.dark .t3e-diff-line.is-add { background: rgba(74, 222, 128, 0.13); border-left-color: #4ade80; }
.dark .t3e-diff-line.is-del { background: rgba(248, 113, 113, 0.14); border-left-color: #f87171; }
.t3e-diff-line.is-hunk { background: var(--cx-card); color: var(--cx-ink-3); }
.t3e-diff-ln { flex: 0 0 36px; padding-right: 10px; text-align: right; color: var(--cx-ink-4); user-select: none; font-variant-numeric: tabular-nums; }
.t3e-diff-line.is-add .t3e-diff-ln { color: #15803d; }
.t3e-diff-line.is-del .t3e-diff-ln { color: #b91c1c; }
.dark .t3e-diff-line.is-add .t3e-diff-ln { color: #86efac; }
.dark .t3e-diff-line.is-del .t3e-diff-ln { color: #fca5a5; }
.t3e-diff-sign { flex: 0 0 14px; text-align: center; user-select: none; color: var(--cx-ink-3); }
.t3e-diff-code { white-space: pre; color: var(--cx-ink-1); }
.t3e-diff-more {
  display: block;
  width: 100%;
  border: 0;
  border-top: 1px solid var(--cx-line-soft);
  padding: 6px 12px;
  background: var(--cx-card);
  color: var(--cx-link);
  font-family: var(--font-sans);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
}
.t3e-diff-more:hover { background: var(--cx-hover); }
.t3e-diff-changes-list { margin: 0; padding: 8px 12px; list-style: none; font-family: var(--font-mono); font-size: 12px; line-height: 19px; color: var(--cx-ink-2); }

/* 3.5 files-changes-explorer (ChatGPT All Changes + Changed Files / All Files split) */
.t3e-fe-changes-wrap {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  padding: 4px 8px 6px;
  gap: 2px;
  border-bottom: 1px solid var(--cx-line-soft);
  box-sizing: border-box;
}
.t3e-fe-all-changes-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  height: 30px;
  padding: 0 8px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--cx-ink-1);
  font-size: 13px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  box-sizing: border-box;
  transition: background-color 140ms ease;
}
.t3e-fe-all-changes-btn:hover { background: var(--cx-hover); }
.t3e-fe-icon { width: 14px; height: 14px; flex-shrink: 0; color: var(--cx-ink-2); }
.t3e-fe-trunc { min-width: 0; flex: 1 1 auto; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.t3e-fe-count {
